const { Given, When, Then, Before, After } = require('@cucumber/cucumber');

// Find a todo list item by title, falling back to data-original-title for renamed items.
function findItem(document, title) {
  const items = document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) return li;
  }
  // Fallback: search by data-original-title for items renamed during edit
  for (const li of items) {
    if (li.getAttribute('data-original-title') === title) return li;
  }
  return null;
}

// ---- Background ----

Given('the app is loaded fresh', function () {
  // Already done by Before hook in world.js
});

Given('the app has no todos', function () {
  // World loads fresh app on each scenario
});

Given('the new todo input is empty', function () {
  // Fresh app starts with empty input by default
});

// ---- Given: todo creation helpers ----

Given('the user has created a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

Given('the user has created a completed todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  // Mark complete
  const todoItems = this.document.querySelectorAll('.todo-list li');
  const toggle = todoItems[todoItems.length - 1].querySelector('.toggle');
  toggle.click();
});

Given('the user has created todos {string}, {string}', function (t1, t2) {
  const input = this.document.querySelector('.new-todo');
  [t1, t2].forEach(t => {
    input.value = t;
    input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  });
});

Given('the user has created todos {string}, {string}, {string}', function (t1, t2, t3) {
  const input = this.document.querySelector('.new-todo');
  [t1, t2, t3].forEach(t => {
    input.value = t;
    input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  });
});

Given('the user has created an active todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

Given('the user has marked all todos complete', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (toggleAll) toggleAll.click();
});

// ---- When: actions ----

When('the user types {string} and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user presses Enter on an empty input', function () {
  const input = this.document.querySelector('.new-todo');
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user clicks the toggle checkbox for {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.toggle').click();
});

When('the user clicks the toggle-all checkbox', function () {
  this.document.querySelector('.toggle-all').click();
});

When('the user clicks the destroy button for {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.destroy').click();
});

When('the user double-clicks the label for {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('the user changes the edit input to {string} and presses Enter', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user changes the edit input to {string} and blurs the input', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user changes the edit input to {string} and presses Escape', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
});

When('the user changes the edit input to {string} and blurs', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user marks {string} as complete', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.toggle').click();
});

When('the user unchecks {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.toggle').click();
});

When('the user checks {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  const toggle = li.querySelector('.toggle');
  if (!toggle.checked) toggle.click();
});

When('the user clicks the clear-completed button', function () {
  this.document.querySelector('.clear-completed').click();
});

When('the user clicks the Active filter link', function () {
  this.navigate('#/active');
  if (this.window.todoApp) this.window.todoApp.render();
});

When('the user clicks the Completed filter link', function () {
  this.navigate('#/completed');
  if (this.window.todoApp) this.window.todoApp.render();
});

When('the user clicks the All filter link', function () {
  this.navigate('#/');
  if (this.window.todoApp) this.window.todoApp.render();
});

When('the user creates a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the app is reloaded', function () {
  // Save state
  var savedData = {};
  for (var i = 0; i < this.window.localStorage.length; i++) {
    var key = this.window.localStorage.key(i);
    savedData[key] = this.window.localStorage.getItem(key);
  }
  var savedHash = this.window.location.hash;

  // Dispose old window
  if (this.window.happyDOM && typeof this.window.happyDOM.close === 'function') {
    this.window.happyDOM.close().catch(function(){});
  }

  // Create new window, load app
  var fs = require('node:fs');
  var path = require('node:path');
  var Window = require('happy-dom').Window;
  var w = new Window({ url: 'http://localhost/', settings: { disableJavaScriptFileLoading: true } });
  var d = w.document;
  d.write(fs.readFileSync(path.resolve(__dirname, '..', '..', 'index.html'), 'utf8'));
  d.close();
  w.eval(fs.readFileSync(path.resolve(__dirname, '..', '..', 'js', 'app.js'), 'utf8'));
  d.dispatchEvent(new w.Event('DOMContentLoaded', { bubbles: true }));
  w.dispatchEvent(new w.Event('load'));

  // Restore localStorage
  var ls = w.localStorage;
  for (var k in savedData) {
    if (savedData.hasOwnProperty(k)) {
      ls.setItem(k, savedData[k]);
    }
  }

  // Restore hash and trigger re-render
  var needsRender = false;
  if (savedHash && savedHash !== '#' && savedHash !== '') {
    w.location.hash = savedHash;
    needsRender = true;
  }

  // Re-init app with restored data
  w.todoApp.init();

  // If hash was restored and init reset it, re-set it and re-render
  if (needsRender && w.location.hash === '') {
    w.location.hash = savedHash;
    w.todoApp.init();
  }

  // Replace the world's window/document
  this.window = w;
  this.document = d;
});

// ---- Then: assertions ----

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display !== 'none' && !main.hidden) {
    throw new Error('Expected main section to be hidden, but it was visible');
  }
});

Then('the footer section is hidden', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  if (style.display !== 'none' && !footer.hidden) {
    throw new Error('Expected footer section to be hidden, but it was visible');
  }
});

Then('the new todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  if (this.document.activeElement !== input) {
    throw new Error('Expected new todo input to have focus');
  }
});

Then('the todo list shows {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length !== count) {
    throw new Error(`Expected ${count} item(s) in todo list, found ${items.length}`);
  }
});

Then('the todo list shows {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li:not(.hidden)');
  const allItems = this.document.querySelectorAll('.todo-list li');
  const visibleItems = [];
  for (const li of allItems) {
    const style = this.window.getComputedStyle(li);
    if (style.display !== 'none' && !li.hidden) {
      visibleItems.push(li);
    }
  }
  if (visibleItems.length !== count) {
    throw new Error(`Expected ${count} item(s) in todo list, found ${visibleItems.length}`);
  }
});

Then('the todo list shows no items', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length > 0) {
    // Check visible items
    let visible = 0;
    for (const li of items) {
      const style = this.window.getComputedStyle(li);
      if (style.display !== 'none' && !li.hidden) visible++;
    }
    if (visible > 0) {
      throw new Error(`Expected no items in todo list, found ${visible}`);
    }
  }
});

Then('the new item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  if (!lastItem) throw new Error('No todo items found');
  const label = lastItem.querySelector('label');
  if (!label) throw new Error('Todo item has no label');
  if (label.textContent !== title) {
    throw new Error(`Expected item title "${title}", got "${label.textContent}"`);
  }
});

Then('the new item is not completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  if (!lastItem) throw new Error('No todo items found');
  if (lastItem.classList.contains('completed')) {
    throw new Error('Expected new item not to be completed');
  }
});

Then('the new todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') {
    throw new Error(`Expected input to be cleared, got "${input.value}"`);
  }
});

Then('the first item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const visibleItems = [];
  for (const li of items) {
    const style = this.window.getComputedStyle(li);
    if (style.display !== 'none' && !li.hidden) visibleItems.push(li);
  }
  // If no visible items, try showing all
  const item = visibleItems.length > 0 ? visibleItems[0] : items[0];
  if (!item) throw new Error('No todo items found');
  const label = item.querySelector('label');
  if (!label) throw new Error('Todo item has no label');
  if (label.textContent !== title) {
    throw new Error(`Expected first item title "${title}", got "${label.textContent}"`);
  }
});

Then('the second item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const visibleItems = [];
  for (const li of items) {
    const style = this.window.getComputedStyle(li);
    if (style.display !== 'none' && !li.hidden) visibleItems.push(li);
  }
  const item = visibleItems.length > 1 ? visibleItems[1] : items[1];
  if (!item) throw new Error('No second todo item');
  const label = item.querySelector('label');
  if (label.textContent !== title) {
    throw new Error(`Expected second item title "${title}", got "${label.textContent}"`);
  }
});

Then('the third item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const visibleItems = [];
  for (const li of items) {
    const style = this.window.getComputedStyle(li);
    if (style.display !== 'none' && !li.hidden) visibleItems.push(li);
  }
  const item = visibleItems.length > 2 ? visibleItems[2] : items[2];
  if (!item) throw new Error('No third todo item');
  const label = item.querySelector('label');
  if (label.textContent !== title) {
    throw new Error(`Expected third item title "${title}", got "${label.textContent}"`);
  }
});

Then('the todo item {string} has the completed class', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  if (!li.classList.contains('completed')) {
    throw new Error(`Expected "${title}" to have completed class`);
  }
});

Then('the todo item {string} does not have the completed class', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  if (li.classList.contains('completed')) {
    throw new Error(`Expected "${title}" not to have completed class`);
  }
});

Then('its checkbox is checked', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  const toggle = lastItem.querySelector('.toggle');
  if (!toggle || !toggle.checked) {
    throw new Error('Expected checkbox to be checked');
  }
});

Then('its checkbox is not checked', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  const toggle = lastItem.querySelector('.toggle');
  if (toggle && toggle.checked) {
    throw new Error('Expected checkbox not to be checked');
  }
});

Then('all todos are marked complete', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length === 0) throw new Error('No todo items');
  for (const li of items) {
    if (!li.classList.contains('completed')) {
      const label = li.querySelector('label');
      throw new Error(`Todo "${label ? label.textContent : 'unknown'}" is not completed`);
    }
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (!toggleAll || !toggleAll.checked) {
    throw new Error('Expected toggle-all to be checked');
  }
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (toggleAll && toggleAll.checked) {
    throw new Error('Expected toggle-all not to be checked');
  }
});

Then('the todo item {string} has the editing class', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  if (!li.classList.contains('editing')) {
    throw new Error(`Expected "${title}" to have editing class`);
  }
});

Then('the todo item {string} does not have the editing class', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  if (li.classList.contains('editing')) {
    throw new Error(`Expected "${title}" not to have editing class`);
  }
});

Then('the todo item has the title {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) {
    // Also check current titles
    const items = this.document.querySelectorAll('.todo-list li');
    for (const item of items) {
      const label = item.querySelector('label');
      if (label && label.textContent === title) return;
    }
    throw new Error(`No item with title "${title}" found`);
  }
});

Then('the todo count shows {string}', function (expected) {
  const countEl = this.document.querySelector('.todo-count');
  if (!countEl) throw new Error('No todo count element found');
  const text = countEl.textContent.trim();
  if (text !== expected) {
    throw new Error(`Expected count "${expected}", got "${text}"`);
  }
});

Then('the count text wraps the number in a <strong> tag', function () {
  const strong = this.document.querySelector('.todo-count strong');
  if (!strong) throw new Error('Expected <strong> tag inside .todo-count');
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('No clear-completed button');
  const style = this.window.getComputedStyle(btn);
  if (style.display !== 'none' && !btn.hidden) {
    throw new Error('Expected clear-completed to be hidden');
  }
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('No clear-completed button');
  const style = this.window.getComputedStyle(btn);
  if (style.display === 'none' || btn.hidden) {
    throw new Error('Expected clear-completed to be visible');
  }
});

Then('the items have titles {string} and {string}', function (t1, t2) {
  const items = this.document.querySelectorAll('.todo-list li');
  const titles = [];
  for (const li of items) {
    const label = li.querySelector('label');
    if (label) titles.push(label.textContent);
  }
  const expected = [t1, t2];
  if (titles.length !== expected.length || titles[0] !== expected[0] || titles[1] !== expected[1]) {
    throw new Error(`Expected titles "${expected}", got "${titles}"`);
  }
});

Then('the localStorage key {string} is set', function (key) {
  const data = this.window.localStorage.getItem(key);
  if (!data) {
    throw new Error(`localStorage key "${key}" is not set`);
  }
});

Then('it contains a todo with title {string}', function (title) {
  const key = 'todos-javascript';
  const data = this.window.localStorage.getItem(key);
  if (!data) throw new Error(`localStorage key "${key}" is not set`);
  const todos = JSON.parse(data);
  if (!Array.isArray(todos)) throw new Error('localStorage data is not an array');
  const found = todos.some(t => t.title === title);
  if (!found) {
    throw new Error(`No todo with title "${title}" found in localStorage`);
  }
});

Then('no todo item has the editing class', function () {
  const editing = this.document.querySelectorAll('.todo-list li.editing');
  if (editing.length > 0) {
    throw new Error(`Expected no items in editing mode, found ${editing.length}`);
  }
});

Then('the first item is not completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const item = items[0];
  if (!item) throw new Error('No todo items found');
  const label = item.querySelector('label');
  const title = label ? label.textContent : 'unknown';
  const hash = this.window.location.hash;
  if (item.classList.contains('completed')) {
    var lsData = this.window.localStorage.getItem('todos-javascript');
    throw new Error(`Expected first item not to be completed, but first item is "${title}" (hash: "${hash}", total items: ${items.length}, localStorage: ${lsData})`);
  }
});

Then('the second item is completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const item = items[1];
  if (!item) throw new Error('No second todo item found');
  if (!item.classList.contains('completed')) {
    throw new Error('Expected second item to be completed');
  }
});

Then('the All filter link has the selected class', function () {
  const links = this.document.querySelectorAll('.filters a');
  const allLink = Array.from(links).find(a => a.textContent === 'All');
  if (!allLink) throw new Error('All filter link not found');
  if (!allLink.classList.contains('selected')) {
    throw new Error('Expected All filter link to have selected class');
  }
});

Then('the Active filter link has the selected class', function () {
  const links = this.document.querySelectorAll('.filters a');
  const activeLink = Array.from(links).find(a => a.textContent === 'Active');
  if (!activeLink) throw new Error('Active filter link not found');
  if (!activeLink.classList.contains('selected')) {
    throw new Error('Expected Active filter link to have selected class');
  }
});

Then('the Completed filter link has the selected class', function () {
  const links = this.document.querySelectorAll('.filters a');
  const completedLink = Array.from(links).find(a => a.textContent === 'Completed');
  if (!completedLink) throw new Error('Completed filter link not found');
  if (!completedLink.classList.contains('selected')) {
    throw new Error('Expected Completed filter link to have selected class');
  }
});

Then('the Active filter link does not have the selected class', function () {
  const links = this.document.querySelectorAll('.filters a');
  const activeLink = Array.from(links).find(a => a.textContent === 'Active');
  if (!activeLink) throw new Error('Active filter link not found');
  if (activeLink.classList.contains('selected')) {
    throw new Error('Expected Active filter link not to have selected class');
  }
});

Then('the All filter link does not have the selected class', function () {
  const links = this.document.querySelectorAll('.filters a');
  const allLink = Array.from(links).find(a => a.textContent === 'All');
  if (!allLink) throw new Error('All filter link not found');
  if (allLink.classList.contains('selected')) {
    throw new Error('Expected All filter link not to have selected class');
  }
});

Then('the item has the title {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) return;
  }
  throw new Error(`No item with title "${title}" found`);
});

Then('the item is completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  // Check if any visible item has completed class
  for (const li of items) {
    const style = this.window.getComputedStyle(li);
    if (style.display !== 'none' && !li.hidden && li.classList.contains('completed')) return;
  }
  // Also check all items
  for (const li of items) {
    if (li.classList.contains('completed')) return;
  }
  throw new Error('No completed todo item found');
});

Then('the todo list shows only active todos', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    if (li.classList.contains('completed')) {
      const style = this.window.getComputedStyle(li);
      if (style.display !== 'none') {
        const label = li.querySelector('label');
        throw new Error(`Completed todo "${label ? label.textContent : 'unknown'}" is visible in Active filter`);
      }
    }
  }
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

