const { Given, When, Then } = require('@cucumber/cucumber');
const fs = require('node:fs');
const path = require('node:path');

/**
 * Find a named method inside the todoApp IIFE in app.js.
 * Returns { body: string } or null.
 */
function findTodoAppFunction(source, name) {
  // Match patterns: "name: function(...)" inside the todoApp object
  const re = new RegExp('(' + name + ')\\s*:\\s*function\\s*\\(', 'g');
  let match;
  while ((match = re.exec(source)) !== null) {
    const startIdx = match.index;
    const braceStart = source.indexOf('{', startIdx);
    if (braceStart === -1) continue;
    let depth = 0;
    let endIdx = -1;
    for (let i = braceStart; i < source.length; i++) {
      if (source[i] === '{') depth++;
      if (source[i] === '}') {
        depth--;
        if (depth === 0) { endIdx = i; break; }
      }
    }
    if (endIdx === -1) continue;
    return { body: source.substring(startIdx, endIdx + 1) };
  }
  return null;
}

Given('the source at {string}', function (filePath) {
  const resolvedPath = path.resolve(__dirname, '..', '..', filePath);
  this.sourceCode = fs.readFileSync(resolvedPath, 'utf8');
  if (!this.sourceCode) {
    throw new Error('Could not read source file: ' + filePath);
  }
});

When('the conformance checker inspects the toggleTodo function', function () {
  const fn = findTodoAppFunction(this.sourceCode, 'toggleTodo');
  if (!fn) throw new Error('Could not find toggleTodo function in source');
  this.currentFunction = fn;
  this.currentFunctionName = 'toggleTodo';
});

When('the conformance checker inspects the render function', function () {
  const fn = findTodoAppFunction(this.sourceCode, 'render');
  if (!fn) throw new Error('Could not find render function in source');
  this.currentFunction = fn;
  this.currentFunctionName = 'render';
});

When('the conformance checker inspects the toggle-all click handler', function () {
  const source = this.sourceCode;
  // Find the bindEvents function first
  const bindEventsFn = findTodoAppFunction(source, 'bindEvents');
  if (!bindEventsFn) throw new Error('Could not find bindEvents function in source');

  // Within bindEvents body, find the toggle-all click handler
  const bindEventsBody = bindEventsFn.body;
  const toggleAllPattern = /querySelector\s*\(\s*['"]\.toggle-all['"]\s*\)\s*\.\s*addEventListener\s*\(\s*['"]click['"]\s*,\s*function\s*\([^)]*\)\s*\{/;
  const match = bindEventsBody.match(toggleAllPattern);
  if (!match) throw new Error('Could not find toggle-all click handler registration');

  const handlerDeclStart = match.index + match[0].length;
  const braceStart = bindEventsBody.indexOf('{', handlerDeclStart - 10);
  if (braceStart === -1) throw new Error('Could not find opening brace of toggle-all handler');

  // Count braces from braceStart+1 to find matching closing brace
  let depth = 1;
  let endIdx = -1;
  for (let i = braceStart + 1; i < bindEventsBody.length; i++) {
    if (bindEventsBody[i] === '{') depth++;
    if (bindEventsBody[i] === '}') {
      depth--;
      if (depth === 0) { endIdx = i; break; }
    }
  }
  if (endIdx === -1) throw new Error('Could not find end of toggle-all click handler');

  this.currentFunction = {
    body: bindEventsBody.substring(braceStart - 1, endIdx + 1)
  };
  this.currentFunctionName = 'toggleAllHandler';
});

Then('toggleTodo must not call render', function () {
  const body = this.currentFunction.body;
  if (/render\s*\(\s*\)/.test(body)) {
    throw new Error('toggleTodo calls render');
  }
});

Then('toggleTodo must toggle the completed class on the existing list item node in-place', function () {
  const body = this.currentFunction.body;
  if (!body.includes('completed')) {
    throw new Error('toggleTodo does not reference completed class');
  }
  if (!/classList\.(toggle|add|remove)/.test(body)) {
    throw new Error('toggleTodo does not use classList API');
  }
});

Then('the handler must not call render', function () {
  const body = this.currentFunction.body;
  if (/render\s*\(\s*\)/.test(body)) {
    throw new Error('Handler calls render');
  }
});

Then('the handler must toggle the completed class on each existing list item node in-place', function () {
  const body = this.currentFunction.body;
  if (!body.includes('completed')) {
    throw new Error('Handler does not reference completed class');
  }
  if (!/classList\.(toggle|add|remove)/.test(body)) {
    throw new Error('Handler does not use classList API');
  }
});

Then('the render function must not reassign innerHTML on the todo-list element', function () {
  const body = this.currentFunction.body;
  if (/innerHTML/.test(body) && /todo-list/.test(body)) {
    throw new Error('render function reassigns innerHTML on todo-list element');
  }
});

Then('the render function must not recreate li elements that already exist', function () {
  const body = this.currentFunction.body;
  if (/createElement\s*\(\s*['"]li['"]\s*\)/.test(body)) {
    throw new Error('render function creates new li elements');
  }
  if (/<li/.test(body)) {
    throw new Error('render function creates new li elements via innerHTML');
  }
});

